'use client';
import { useState, useEffect, useCallback } from 'react';
import Sidebar from './Sidebar';
import ConfigPanel from './ConfigPanel';
import LivePreview from './LivePreview';

export type Mode = 'tabular' | 'relational' | 'document';

// Default config per mode — prevents stale fields from a previous mode being sent
const DEFAULT_CONFIG: Record<Mode, any> = {
  tabular:    { rowCount: 10, schema: 'id, name, email, role, status, createdAt' },
  relational: { rowCount: 10, schema: 'Users(id, name, email), Orders(id, user_id, product, total, status)' },
  document:   { query: 'A professional invoice for software consulting services rendered in September 2026.' },
};

export default function Workspace() {
  const [activeMode, setActiveMode] = useState<Mode>('tabular');
  const [config, setConfig] = useState<any>(DEFAULT_CONFIG.tabular);
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // FIX: When switching modes, reset config to the mode's defaults and clear stale data/errors.
  // Without this, old schema/query values from a previous mode get sent to the wrong API endpoint.
  const handleModeChange = useCallback((mode: Mode) => {
    setActiveMode(mode);
    setConfig(DEFAULT_CONFIG[mode]);
    setData(null);
    setError(null);
  }, []);

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setData(null);

    try {
      const response = await fetch(`/api/generate/${activeMode}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config),
      });

      const result = await response.json();

      if (!response.ok) {
        // Surface the actual error message returned by the API route
        throw new Error(result.error || `Server error: ${response.status} ${response.statusText}`);
      }

      if (!result.data) {
        throw new Error('No data was returned from the server. The AI response may have been empty.');
      }

      setData(result.data);
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const [mounted, setMounted] = useState(false);
  useEffect(() => { setMounted(true); }, []);

  // Hydration-safe: render a matching skeleton on first paint instead of null.
  // Returning null causes React to mismatch SSR vs client tree, producing hydration warnings.
  if (!mounted) {
    return (
      <div className="flex h-screen overflow-hidden bg-background">
        <div className="w-64 border-r border-border bg-black/40" />
        <div className="flex-1" />
        <div className="w-80 border-l border-border bg-black/40" />
      </div>
    );
  }

  return (
    <div className="flex h-screen overflow-hidden bg-background">
      <Sidebar activeMode={activeMode} setActiveMode={handleModeChange} />
      
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 border-b border-border bg-black/20 backdrop-blur-sm z-10">
          <h1 className="text-xl font-semibold bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
            HackDataV2 Studio
          </h1>
          <div className="flex items-center space-x-4">
            <span className="text-sm text-muted-foreground flex items-center">
              <span className="w-2 h-2 rounded-full bg-green-500 mr-2 animate-pulse" />
              Gemini API Connected
            </span>
          </div>
        </header>
        
        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 flex flex-col p-6 overflow-hidden relative">
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-blue-900/20 via-background to-background pointer-events-none" />
            <LivePreview data={data} loading={loading} error={error} mode={activeMode} />
          </div>
          
          <ConfigPanel 
            mode={activeMode} 
            config={config} 
            setConfig={setConfig} 
            onGenerate={handleGenerate}
            loading={loading}
          />
        </div>
      </main>
    </div>
  );
}
